"""Analyse Immo — application web autonome (FastAPI).

Lancement local : uvicorn main:app --reload
Lancement serveur : uvicorn main:app --host 0.0.0.0 --port $PORT
"""

import datetime as dt
import re
import threading
import unicodedata
from html import escape
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import pandas as pd
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, JSONResponse, RedirectResponse, Response
from jinja2 import DictLoader, Environment, select_autoescape
from fastapi.templating import Jinja2Templates

import graphiques
from immo import (actualite, annonces, config, demande, dvf, export, geo, population,
                  projection, proprietaires, secteurs)
from immo.http import SourceError

RACINE = Path(__file__).resolve().parent
app = FastAPI(title="Analyse Immo")

gabarits = Jinja2Templates(
    env=Environment(loader=DictLoader(_GABARITS), autoescape=select_autoescape(['html']))
)

# Une seule analyse a la fois : les fichiers DVF sont volumineux.
EXECUTEUR = ThreadPoolExecutor(max_workers=1)
TRAVAUX: dict[str, dict] = {}
VERROU = threading.Lock()
DUREE_VALIDITE = dt.timedelta(hours=12)

NOM_SITE = "Analyse Immo"
BASELINE = "Étude de marché communale pour l'achat-revente"


def _sans_accents(texte: str) -> str:
    return "".join(
        c for c in unicodedata.normalize("NFD", texte or "") if unicodedata.category(c) != "Mn"
    ).lower()


def resoudre(code: str) -> dict:
    """Fiche d'identite d'une commune ou d'un arrondissement municipal."""
    info = dvf.info_arrondissement(code)
    if info:
        fiche = {
            "nom": info["nom"],
            "code": code,
            "codeDepartement": info["departement"],
            "codesPostaux": [info["code_postal"]],
            "population": None,
            "ville_mere": info["ville"],
            "code_ville_mere": info["parent"],
        }
        try:  # la population de l'arrondissement n'est pas toujours publiee
            fiche["population"] = geo.par_code(code).get("population")
        except SourceError:
            pass
        return fiche
    return geo.par_code(code)


def suggestions(requete: str, limite: int = 24) -> list[dict]:
    """Communes correspondantes, et les arrondissements des villes qui en ont."""
    texte = _sans_accents(requete).strip()
    chiffres = re.findall(r"\d+", texte)
    resultats: list[dict] = []

    for commune in geo.chercher(requete, limite=6):
        resultats.append(
            {
                "code": commune["code"],
                "nom": commune["nom"],
                "departement": commune.get("codeDepartement"),
                "code_postal": (commune.get("codesPostaux") or [""])[0],
                "population": commune.get("population"),
                "detail": "",
            }
        )
        for code_arr, nom in dvf.ARRONDISSEMENTS.get(commune["code"], []):
            info = dvf.INFO_ARRONDISSEMENTS[code_arr]
            if chiffres and not any(
                n.lstrip("0") == str(info["rang"]) or n == info["code_postal"] for n in chiffres
            ):
                continue
            resultats.append(
                {
                    "code": code_arr,
                    "nom": nom,
                    "departement": info["departement"],
                    "code_postal": info["code_postal"],
                    "population": None,
                    "detail": f"arrondissement de {info['ville']}",
                }
            )

    # Saisie directe d'un arrondissement : « paris 11e », « lyon 3 », « 75011 »
    if not resultats:
        for code_arr, info in dvf.INFO_ARRONDISSEMENTS.items():
            cible = _sans_accents(info["nom"])
            if texte and (texte in cible or texte == info["code_postal"]):
                resultats.append(
                    {
                        "code": code_arr,
                        "nom": info["nom"],
                        "departement": info["departement"],
                        "code_postal": info["code_postal"],
                        "population": None,
                        "detail": f"arrondissement de {info['ville']}",
                    }
                )
    return resultats[:limite]


# --------------------------------------------------------------------------- #
# Collecte des données
# --------------------------------------------------------------------------- #
def _collecter(code: str, commune: dict, profondeur: int, fenetre: int, seuil: int) -> dict:
    travail = TRAVAUX[code]
    resultat: dict = {"commune": commune}

    travail["etape"] = "Populations légales (Insee)"
    resultat["population"] = population.analyse(code, commune.get("population"))

    travail["etape"] = "Ventes immobilières (DVF — DGFiP)"
    try:
        annees = dvf.annees_disponibles(code, profondeur=profondeur)
        ventes, annees = dvf.charger_prepare(code, annees)
        resultat["annees"] = annees
        resultat["ventes"] = ventes
        resultat["erreur_dvf"] = None
    except SourceError as exc:
        resultat["ventes"] = pd.DataFrame()
        resultat["annees"] = []
        resultat["erreur_dvf"] = str(exc)

    ventes = resultat["ventes"]
    travail["etape"] = "Prix au m² et typologies"
    resultat["table_prix"] = dvf.prix_par_annee(ventes) if not ventes.empty else pd.DataFrame()
    resultat["evolution_prix"] = (
        dvf.evolution_prix(resultat["table_prix"], recul=3) if not resultat["table_prix"].empty else None
    )
    resultat["evolution_appartement"] = (
        dvf.evolution_prix(resultat["table_prix"], recul=3, colonne="prix_m2_median_appartement")
        if not resultat["table_prix"].empty
        else None
    )
    resultat["evolution_maison"] = (
        dvf.evolution_prix(resultat["table_prix"], recul=3, colonne="prix_m2_median_maison")
        if not resultat["table_prix"].empty
        else None
    )
    resultat["projection"] = (
        projection.projeter(resultat["table_prix"], horizon=2)
        if not resultat["table_prix"].empty
        else None
    )
    resultat["demande"] = (
        demande.analyser(ventes, mois=fenetre, seuil_ventes=seuil) if not ventes.empty else pd.DataFrame()
    )
    resultat["synthese_demande"] = (
        demande.synthese(resultat["demande"]) if not resultat["demande"].empty else {}
    )
    travail["etape"] = "Découpage par secteurs"
    ventes_secteurs, mode = secteurs.decouper(ventes) if not ventes.empty else (ventes, "aucun")
    resultat["mode_secteurs"] = mode
    table_secteurs = (
        secteurs.analyser(ventes_secteurs, mois=fenetre) if mode != "aucun" else pd.DataFrame()
    )
    if not table_secteurs.empty and not resultat["table_prix"].empty:
        recentes = dvf.periode_recente(ventes_secteurs, fenetre)
        table_secteurs = secteurs.ecart_a_la_ville(
            table_secteurs, float(recentes["prix_m2"].median()) if len(recentes) else None
        )
    resultat["secteurs"] = table_secteurs

    resultat["couverture"] = dvf.couverture(ventes)
    resultat["fenetre"] = fenetre

    travail["etape"] = "Profil des propriétaires (recensement)"
    try:
        resultat["proprietaires"] = proprietaires.profil(code)
    except Exception:  # noqa: BLE001 - une table absente ou illisible ne bloque rien
        resultat["proprietaires"] = {"disponible": False}

    travail["etape"] = "Actualité locale et équipements"
    try:
        resultat["actualites"] = actualite.actualites(commune["nom"], commune.get("codeDepartement"), 24)
    except SourceError as exc:
        resultat["actualites"] = {"themes": {}, "erreurs": [str(exc)]}
    try:
        resultat["ecoles"] = actualite.equipements_scolaires(code)
    except SourceError:
        resultat["ecoles"] = None

    resultat["horodatage"] = dt.datetime.now()
    return resultat


def _executer(code: str, commune: dict, profondeur: int, fenetre: int, seuil: int) -> None:
    try:
        donnees = _collecter(code, commune, profondeur, fenetre, seuil)
        with VERROU:
            TRAVAUX[code].update({"statut": "pret", "donnees": donnees, "etape": "Terminé"})
    except Exception as exc:  # noqa: BLE001 - toute panne doit remonter a l'ecran
        with VERROU:
            TRAVAUX[code].update({"statut": "erreur", "message": str(exc), "etape": "Interrompu"})


def lancer(code: str, commune: dict, profondeur: int = 6, fenetre: int = 24, seuil: int = 5) -> dict:
    """Demarre (ou reutilise) l'analyse d'une commune."""
    with VERROU:
        travail = TRAVAUX.get(code)
        if travail:
            frais = (
                travail.get("statut") == "pret"
                and travail["donnees"]["horodatage"] > dt.datetime.now() - DUREE_VALIDITE
                and travail.get("parametres") == (profondeur, fenetre, seuil)
            )
            if frais or travail.get("statut") == "en_cours":
                return travail
        TRAVAUX[code] = {
            "statut": "en_cours",
            "etape": "Initialisation",
            "commune": commune,
            "parametres": (profondeur, fenetre, seuil),
            "debut": dt.datetime.now(),
        }
    EXECUTEUR.submit(_executer, code, commune, profondeur, fenetre, seuil)
    return TRAVAUX[code]


# --------------------------------------------------------------------------- #
# Mise en forme pour les gabarits
# --------------------------------------------------------------------------- #
def _euros(valeur, suffixe: str = "") -> str:
    if valeur is None or (isinstance(valeur, float) and pd.isna(valeur)):
        return "n.d."
    return f"{valeur:,.0f}".replace(",", " ") + f" €{suffixe}"


def _nombre(valeur) -> str:
    if valeur is None or (isinstance(valeur, float) and pd.isna(valeur)):
        return "n.d."
    return f"{valeur:,.0f}".replace(",", " ")


def _contexte_ville(donnees: dict) -> dict:
    pop = donnees["population"]
    table_prix = donnees["table_prix"]
    demande_table = donnees["demande"]

    serie_pop = pop.get("serie") or {}
    graphe_population = graphiques.courbe(
        [{"nom": "Population municipale", "points": [(a, v) for a, v in sorted(serie_pop.items())]}],
        titre_accessible="Évolution de la population municipale",
        info_suffixe=" habitants",
    )

    series_prix = []
    if not table_prix.empty:
        for nom, colonne, couleur in (
            ("Appartement", "prix_m2_median_appartement", graphiques.SERIE_1),
            ("Maison", "prix_m2_median_maison", graphiques.SERIE_2),
        ):
            points = [
                (int(ligne["annee"]), float(ligne[colonne]))
                for _, ligne in table_prix.iterrows()
                if pd.notna(ligne.get(colonne))
            ]
            if len(points) >= 2:
                series_prix.append({"nom": nom, "points": points, "couleur": couleur})
        if not series_prix:
            points = [
                (int(ligne["annee"]), float(ligne["prix_m2_median"]))
                for _, ligne in table_prix.iterrows()
                if pd.notna(ligne["prix_m2_median"])
            ]
            if len(points) >= 2:
                series_prix.append({"nom": "Tous biens", "points": points})
    graphe_prix = graphiques.courbe(
        series_prix, unite=" €", titre_accessible="Évolution du prix médian au m²",
        info_suffixe="/m² médian",
    )

    classees = demande_table[demande_table["retenu"]] if not demande_table.empty else pd.DataFrame()
    graphe_demande = graphiques.barres(
        [
            {"libelle": ligne["segment"], "valeur": round(float(ligne["score_demande"]), 1)}
            for _, ligne in classees.iterrows()
        ]
        if not classees.empty
        else [],
        info_suffixe="/100",
    )
    graphe_volumes = graphiques.barres(
        [
            {"libelle": ligne["segment"], "valeur": int(ligne["ventes_recentes"]), "couleur": graphiques.NEUTRE}
            for _, ligne in classees.iterrows()
        ]
        if not classees.empty
        else [],
        info_suffixe=" ventes sur la période",
    )

    lignes_prix = []
    if not table_prix.empty:
        for _, ligne in table_prix.iterrows():
            lignes_prix.append(
                {
                    "annee": int(ligne["annee"]),
                    "ventes": int(ligne["ventes"]),
                    "median": _euros(ligne["prix_m2_median"], "/m²"),
                    "moyen": _euros(ligne["prix_m2_moyen"], "/m²"),
                    "appartement": _euros(ligne.get("prix_m2_median_appartement"), "/m²"),
                    "maison": _euros(ligne.get("prix_m2_median_maison"), "/m²"),
                    "prix_bien": _euros(ligne["prix_median"]),
                    "surface": f"{ligne['surface_mediane']:.0f} m²" if pd.notna(ligne["surface_mediane"]) else "n.d.",
                }
            )

    lignes_demande = []
    if not demande_table.empty:
        for _, ligne in demande_table.iterrows():
            lignes_demande.append(
                {
                    "segment": ligne["segment"],
                    "classee": bool(ligne["retenu"]),
                    "score": f"{ligne['score_demande']:.0f}" if pd.notna(ligne["score_demande"]) else "—",
                    "ventes": int(ligne["ventes_recentes"]),
                    "part": (
                        f"{ligne['part_marche_pct']:.1f}".replace(".", ",") + " %"
                        if pd.notna(ligne["part_marche_pct"]) else "n.d."
                    ),
                    "volume": graphiques.variation(
                        float(ligne["evolution_volume_pct"]) if pd.notna(ligne["evolution_volume_pct"]) else None
                    ),
                    "prix_m2": _euros(ligne["prix_m2_median"], "/m²"),
                    "prix_bien": _euros(ligne["prix_median"]),
                    "surface": f"{ligne['surface_mediane']:.0f} m²" if pd.notna(ligne["surface_mediane"]) else "n.d.",
                    "evolution_prix": graphiques.variation(
                        float(ligne["evolution_prix_m2_3ans_pct"])
                        if pd.notna(ligne["evolution_prix_m2_3ans_pct"])
                        else None
                    ),
                }
            )

    synthese = donnees.get("synthese_demande") or {}
    plus = synthese.get("plus_demandes")
    moins = synthese.get("moins_demandes")

    def _resume(table):
        if table is None or table.empty:
            return []
        return [
            {
                "segment": ligne["segment"],
                "score": f"{ligne['score_demande']:.0f}",
                "commentaire": demande.commentaire(ligne),
                "prix_m2": _euros(ligne["prix_m2_median"], "/m²"),
            }
            for _, ligne in table.iterrows()
        ]

    table_secteurs = donnees.get("secteurs")
    lignes_secteurs, graphe_secteurs, graphe_tension = [], "", ""
    if table_secteurs is not None and not table_secteurs.empty:
        classes = table_secteurs[table_secteurs["retenu"]]
        graphe_secteurs = graphiques.barres(
            [
                {"libelle": ligne["secteur"], "valeur": round(float(ligne["prix_m2_median"]))}
                for _, ligne in classes.iterrows()
            ],
            unite="\u202f€",
            info_suffixe="/m² médian",
        )
        graphe_tension = graphiques.barres(
            [
                {"libelle": ligne["secteur"], "valeur": round(float(ligne["score_tension"]), 1),
                 "couleur": graphiques.NEUTRE}
                for _, ligne in classes.iterrows()
                if pd.notna(ligne["score_tension"])
            ],
            info_suffixe="/100 de tension",
        )
        codes_secteurs = {
            nom: code
            for code, nom in (
                (c, n) for c, n in dvf.ARRONDISSEMENTS.get(donnees["commune"]["code"], [])
            )
        }
        for _, ligne in table_secteurs.iterrows():
            lignes_secteurs.append(
                {
                    "secteur": ligne["secteur"],
                    "code": codes_secteurs.get(ligne["secteur"]),
                    "retenu": bool(ligne["retenu"]),
                    "ventes": int(ligne["ventes"]),
                    "part": (
                        f"{ligne['part_marche_pct']:.1f}".replace(".", ",") + "\u202f%"
                        if pd.notna(ligne["part_marche_pct"]) else "n.d."
                    ),
                    "prix_m2": _euros(ligne["prix_m2_median"], "/m²"),
                    "prix_bien": _euros(ligne["prix_median"]),
                    "surface": f"{ligne['surface_mediane']:.0f} m²" if pd.notna(ligne["surface_mediane"]) else "n.d.",
                    "evolution": graphiques.variation(
                        float(ligne["evolution_prix_3ans_pct"]) if pd.notna(ligne["evolution_prix_3ans_pct"]) else None
                    ),
                    "ecart": graphiques.variation(
                        float(ligne["ecart_ville_pct"]) if pd.notna(ligne.get("ecart_ville_pct")) else None
                    ),
                    "typologie": ligne["typologie_dominante"],
                    "part_typologie": (
                        f"{ligne['part_typologie_pct']:.0f}\u202f%" if pd.notna(ligne["part_typologie_pct"]) else ""
                    ),
                    "tension": f"{ligne['score_tension']:.0f}" if pd.notna(ligne["score_tension"]) else "—",
                }
            )

    # --- Projection du prix au m² ---
    prevision = donnees.get("projection")
    graphe_projection = ""
    phrase_projection = ""
    scenarios = []
    if prevision and prevision.get("possible"):
        graphe_projection = graphiques.projection(prevision["historique"], prevision["points"])
        phrase_projection = projection.phrase(prevision)
        scenarios = [
            {
                "nom": "Prudent",
                "prix": _euros(prevision["bas"], "/m²"),
                "variation": graphiques.variation(prevision["variation_bas_pct"]),
                "lecture": "si la tendance s'essouffle ou se retourne",
            },
            {
                "nom": "Central",
                "prix": _euros(prevision["central"], "/m²"),
                "variation": graphiques.variation(prevision["variation_pct"]),
                "lecture": "prolongement amorti de la tendance observée",
            },
            {
                "nom": "Favorable",
                "prix": _euros(prevision["haut"], "/m²"),
                "variation": graphiques.variation(prevision["variation_haut_pct"]),
                "lecture": "si la dynamique récente se maintient pleinement",
            },
        ]

    # --- Propriétaires par tranche d'âge ---
    profil = donnees.get("proprietaires") or {"disponible": False}
    lignes_proprietaires, graphe_proprietaires, phrases_proprietaires = [], "", []
    colonnes_proprietaires = profil.get("colonnes") or []
    if profil.get("disponible") and not profil.get("vide"):
        phrases_proprietaires = proprietaires.phrases(profil)
        graphe_proprietaires = graphiques.barres(
            [
                {"libelle": ligne["tranche_age"], "valeur": round(ligne["part_parc_pct"], 1)}
                for ligne in profil["ages"]
            ],
            unite="\u202f%",
            info_suffixe=" du parc détenu",
        )
        for ligne in profil["ages"]:
            lignes_proprietaires.append(
                {
                    "tranche_age": ligne["tranche_age"],
                    "menages": _nombre(ligne["menages"]),
                    "part": f"{ligne['part_parc_pct']:.1f}".replace(".", ",") + "\u202f%",
                    "dominante": ligne["typologie_dominante"],
                    "part_dominante": f"{ligne['part_dominante_pct']:.0f}\u202f%",
                    "repartition": {
                        typo: f"{ligne['repartition'].get(typo, 0):.0f}\u202f%"
                        for typo in colonnes_proprietaires
                    },
                }
            )

    derniere = table_prix.iloc[-1] if not table_prix.empty else None

    # --- Chiffres clés repris dans l'en-tête de chaque section repliée ---
    # Une section fermée doit rester informative : son titre porte le chiffre
    # qui justifie de l'ouvrir.
    resumes: dict[str, str] = {}
    if pop.get("population_actuelle"):
        resume = _nombre(pop["population_actuelle"]) + " habitants"
        if pop.get("moyen_terme"):
            resume += " · " + graphiques.variation(pop["moyen_terme"]["variation_pct"]) + " sur 5 ans"
        resumes["demographie"] = resume
    if derniere is not None:
        resume = _euros(derniere["prix_m2_median"], "/m²")
        if donnees["evolution_prix"]:
            resume += " · " + graphiques.variation(donnees["evolution_prix"]["variation_pct"]) + " sur 3 ans"
        resumes["prix"] = resume
    if plus is not None and not plus.empty:
        tete = plus.iloc[0]
        resumes["typologies"] = (
            f"{escape(str(tete['segment']))} en tête · {round(float(tete['score_demande']))}/100"
        )
    if prevision and prevision.get("possible"):
        resumes["projection"] = (
            graphiques.variation(prevision["variation_pct"]) + f" d'ici {prevision['annee_cible']}"
        )
    elif prevision:
        resumes["projection"] = "série trop courte"
    if lignes_proprietaires:
        tete_age = max(profil["ages"], key=lambda l: l["part_parc_pct"])
        resumes["proprietaires"] = (
            f"{escape(tete_age['tranche_age'])} en tête · "
            f"{tete_age['part_parc_pct']:.0f}\u202f% du parc, surtout des "
            f"{escape(tete_age['typologie_dominante'])}"
        )
    if lignes_secteurs:
        retenus = [l for l in lignes_secteurs if l["retenu"]]
        mot = "arrondissement" if donnees.get("mode_secteurs") == "arrondissement" else "secteur"
        accord = "s" if len(retenus) > 1 else ""
        resumes["secteurs"] = f"{len(retenus)} {mot}{accord} analysé{accord}"
        if len(retenus) < len(lignes_secteurs):
            resumes["secteurs"] += f" sur {len(lignes_secteurs)}"
    nombre_articles = sum(len(a) for a in (donnees["actualites"].get("themes") or {}).values())
    if nombre_articles:
        pluriel = "s" if nombre_articles > 1 else ""
        resumes["actualite"] = f"{nombre_articles} article{pluriel} sur 24 mois"
        if donnees["ecoles"]:
            resumes["actualite"] += f" · {donnees['ecoles']['total']} établissements scolaires"
    if donnees["couverture"]:
        resumes["couverture"] = f"{_nombre(donnees['couverture']['ventes'])} ventes exploitées"
    resumes["sources"] = f"{len(config.SOURCES)} jeux de données publiques"

    # --- Sources, avec les millésimes réellement mobilisés pour cette commune ---
    annees = donnees["annees"] or []
    periode = f"{annees[0]}–{annees[-1]}" if annees else "années disponibles"
    millesimes = ", ".join(str(a) for a in sorted(serie_pop)) if serie_pop else "millésimes Insee"
    sources = []
    for source in config.SOURCES:
        note = source["note"].format(millesimes=millesimes, annees=periode) if source["note"] else ""
        sources.append({**source, "note": note})

    return {
        "commune": donnees["commune"],
        "population": pop,
        "population_actuelle": _nombre(pop.get("population_actuelle")),
        "court_terme": pop.get("court_terme"),
        "moyen_terme": pop.get("moyen_terme"),
        "prix_median": _euros(derniere["prix_m2_median"], "/m²") if derniere is not None else "n.d.",
        "annee_prix": int(derniere["annee"]) if derniere is not None else None,
        "ventes_annee": int(derniere["ventes"]) if derniere is not None else 0,
        "evolution_prix": donnees["evolution_prix"],
        "evolution_appartement": donnees["evolution_appartement"],
        "evolution_maison": donnees["evolution_maison"],
        "graphe_population": graphe_population,
        "graphe_prix": graphe_prix,
        "graphe_demande": graphe_demande,
        "graphe_volumes": graphe_volumes,
        "lignes_prix": lignes_prix,
        "lignes_demande": lignes_demande,
        "plus_demandes": _resume(plus),
        "moins_demandes": _resume(moins),
        "serie_population": sorted(serie_pop.items()),
        "projection": prevision,
        "graphe_projection": graphe_projection,
        "phrase_projection": phrase_projection,
        "scenarios": scenarios,
        "lignes_proprietaires": lignes_proprietaires,
        "graphe_proprietaires": graphe_proprietaires,
        "phrases_proprietaires": phrases_proprietaires,
        "colonnes_proprietaires": colonnes_proprietaires,
        "proprietaires_disponible": bool(profil.get("disponible") and not profil.get("vide")),
        "lignes_secteurs": lignes_secteurs,
        "graphe_secteurs": graphe_secteurs,
        "graphe_tension": graphe_tension,
        "mode_secteurs": donnees.get("mode_secteurs", "aucun"),
        "actualites": donnees["actualites"],
        "ecoles": donnees["ecoles"],
        "couverture": donnees["couverture"],
        "annees": donnees["annees"],
        "erreur_dvf": donnees["erreur_dvf"],
        "fenetre": donnees["fenetre"],
        "variation": graphiques.variation,
        "horodatage": donnees["horodatage"],
        "resumes": resumes,
        "sources": sources,
    }


